const EMOJI_COUNT = OFFSETS.length - 1;

// Lazily-built emoji strings �?building once is cheap (~333 small strings)
// but we still defer until first use to keep cold start fast.
let emojiTable: string[] | undefined;

function getEmojiTable(): string[] {
  if(emojiTable) return emojiTable;
  const out: string[] = new Array(EMOJI_COUNT);
  for(let i = 0; i < EMOJI_COUNT; i++) {
    const start = OFFSETS[i];
    const end = OFFSETS[i + 1];
    let s = '';
    for(let j = start; j < end; j++) {
      s += String.fromCharCode(EMOJI_CODE_UNITS[j]);
    }
    out[i] = s;
  }
  emojiTable = out;
  return out;
}

// Compute one emoji index from 8 input bytes, big-endian, with the top bit
// cleared (so the result fits comfortably below 2^53 �?JS' integer-safe limit).
// Matches `ComputeEmojiIndex` in tdesktop's calls_emoji_fingerprint.cpp.
function emojiIndexFromChunk(bytes: Uint8Array, offset: number): number {
  // Manually combine 8 bytes into a Number. We use plain arithmetic (not
  // bitwise) for the high bytes because bitwise operators in JS work in
  // 32-bit signed integers �?multiplying preserves the full precision up to
  // 2^53. The top bit of byte 0 is cleared before assembly.
  const b0 = bytes[offset] & 0x7f;
  const b1 = bytes[offset + 1];
  const b2 = bytes[offset + 2];
  const b3 = bytes[offset + 3];
  const b4 = bytes[offset + 4];
  const b5 = bytes[offset + 5];
  const b6 = bytes[offset + 6];
  const b7 = bytes[offset + 7];
  // Hi 32 bits then lo 32 bits, then assemble.
  const hi = b0 * 0x1000000 + (b1 << 16) + (b2 << 8) + b3;
  const lo = b4 * 0x1000000 + (b5 << 16) + (b6 << 8) + b7;
  // index = hi * 2^32 + lo, mod EMOJI_COUNT (avoid bigint for speed).
  // We use the identity (hi * 2^32 + lo) mod N == (((hi mod N) * (2^32 mod N)) + (lo mod N)) mod N.
  const N = EMOJI_COUNT;
  const POW32_MOD_N = (Math.pow(2, 32) % N);
  return Math.floor(((hi % N) * POW32_MOD_N + (lo % N)) % N);
}

// Render an emoji_hash (32 bytes) as a list of 4 emoji strings.
// Inputs of other lengths are accepted, as long as length is a multiple of 8.
export function emojiFingerprint(emojiHash: Uint8Array): string[] {
  if(emojiHash.length % 8 !== 0) {
    throw new Error(
      `emojiFingerprint: length must be a multiple of 8, got ${emojiHash.length}`
    );
  }
  const table = getEmojiTable();
  const count = emojiHash.length / 8;
  const out: string[] = new Array(count);
  for(let i = 0; i < count; i++) {
    const idx = emojiIndexFromChunk(emojiHash, i * 8);
    out[i] = table[idx];
  }
  return out;
}

// Convenience: 4 emojis joined by a separator (default: zero-width-joiner
// alternative; here just a space so they render as separate glyphs).
export function emojiFingerprintString(emojiHash: Uint8Array, separator = ' '): string {
  return emojiFingerprint(emojiHash).join(separator);
}

// Exposed for tests + UI components that want the raw emoji list.
export function getFingerprintEmojiCount(): number {
  return EMOJI_COUNT;
}
